from builtins import object
from taf.ul.trs_e2e_fw.lib.networking_devices.exceptions import SwitchNotSupportedException
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.juniper import JuniperSsh
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.tps import TPSSsh
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.nokia import NokiaSsh
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.nokia import NokiaTelnet
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.cisco import CiscoSsh
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.cisco import CiscoTelnet
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.mwr import MwrTelnet
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.mwr import MwrSsh
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.netgear import NetgearTelnet
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler


class SwitchManager(object):
    """
    This class contains the method to create switch object based on the switch type mentioned
    in the configuration file.
    """

    def __init__(self):
        self.config = ConfigHandler.get_config()

    def configure_switch(self, device, command_profile, **kwargs):
        """
        The method is used to create a switch object based on the configuration file input for
        switch device and it
        calls the configure_switch of the corresponding object.

        Args:
        device: device section of the switch section from config file
        command_profile: command profile name from the testline config file inside switch section

        Returns:
        :param

        """
        switch_obj = SwitchFactory(device, command_profile).create_switch_object()
        switch_obj.configure_switch(**kwargs)


class SwitchFactory(object):
    """
    Factory classes to create switch objects. Factory classes are used to generate the objects
    without exposing the implementation details to the caller of the class methods.
    """

    def __init__(self, device, command_profile):
        self.config = ConfigHandler.get_config()
        self.device = device
        self.command_profile = command_profile

    def create_switch_object(self):
        """
        This method creates the which objects based on the "connction_type" and "make" of the
        switch. If make and connection type is not in config file, then Switch not Supported
        Exception is thrown.
        For example : if make us nokia abd connection type is ssh, then NokiaSsh object will
            be created.
        Returns: Object based on the connection type and make

        """
        connection_type = get_config_variable(['switch', self.device, 'connection_type']) or 'telnet'
        make_type = get_config_variable(['switch', self.device, 'make'])

        if connection_type.lower() == 'ssh' and make_type.lower() == 'nokia':
            return NokiaSsh(self.device, self.command_profile)
        elif connection_type.lower() == 'telnet' and make_type.lower() == 'nokia':
            return NokiaTelnet(self.device, self.command_profile)
        elif connection_type.lower() == 'ssh' and make_type.lower() == 'cisco':
            return CiscoSsh(self.device, self.command_profile)
        elif connection_type.lower() == 'telnet' and make_type.lower() == 'cisco':
            return CiscoTelnet(self.device, self.command_profile)
        elif connection_type.lower() == 'telnet' and make_type.lower() == 'mwr':
            return MwrTelnet(self.device, self.command_profile)
        elif connection_type.lower() == 'ssh' and make_type.lower() == 'mwr':
            return MwrSsh(self.device, self.command_profile)
        elif connection_type.lower() == 'ssh' and make_type.lower() == "juniper":
            return JuniperSsh(self.device, self.command_profile)
        elif connection_type.lower() == 'telnet' and make_type.lower() == 'netgear':
            return NetgearTelnet(self.device, self.command_profile)
        elif connection_type.lower() == "ssh" and make_type.lower() == 'tps':
            return TPSSsh(self.device, self.command_profile)
        else:
            raise SwitchNotSupportedException("{} is not supported for {} switch".format(connection_type, self.device))
